import unittest
from solution import shortest_path

class TestMatrixPathfinder(unittest.TestCase):
    def test_direct_path(self):
        grid = [
            [0, 0, 0],
            [1, 1, 0],
            [0, 0, 0]
        ]
        self.assertEqual(shortest_path(grid, (0, 0), (2, 2)), 5)

    def test_blocked(self):
        grid = [
            [0, 1],
            [1, 0]
        ]
        self.assertEqual(shortest_path(grid, (0, 0), (1, 1)), -1)

    def test_start_equals_end(self):
        grid = [[0]]
        self.assertEqual(shortest_path(grid, (0, 0), (0, 0)), 1)

if __name__ == '__main__':
    unittest.main()
